def possible_change(coins, total):
    if total == 0:
        return 1
    if total < 0:
        return 0

    if not coins:
        return 0

    first, *rest = coins
    return possible_change(rest, total) + possible_change(coins, total - first)

print(possible_change([1, 4, 2], -7))
print(possible_change([1, 5, 10, 25], 11))
print(possible_change([1, 5, 10, 25], 75))
